begin;
-- Positive privileged fixtures represent a completed MFA verification.
select set_config('request.jwt.claims','{"aal":"aal2"}',true);
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(1);
create function pg_temp.assert_measurement(v boolean,msg text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Measurement: %',msg;end if;end $$;
create function pg_temp.deny_measurement(statement text) returns void language plpgsql as $$begin begin execute statement;exception when others then return;end;raise exception 'Expected rejection';end $$;
insert into auth.users(id) values('dc110000-0000-4000-8000-000000000001'),('dc110000-0000-4000-8000-000000000002');
insert into public.profiles(id,branch_code,full_name,is_active) values('dc110000-0000-4000-8000-000000000001','DPS','[CONTOH] Range QA',true),('dc110000-0000-4000-8000-000000000002','DPS','[CONTOH] Range QA Coordinator',true);
insert into public.user_role_assignments(profile_id,branch_code,role_code,grant_reason) values('dc110000-0000-4000-8000-000000000001','DPS','admin','[CONTOH] Range rollback QA'),('dc110000-0000-4000-8000-000000000002','DPS','coordinator','[CONTOH] Range rollback QA');
insert into public.portfolios(id,branch_code,code,name) values('dc220000-0000-4000-8000-000000000001','DPS','CONTOH_RANGE','[CONTOH] Ranges');
select set_config('request.jwt.claim.sub','dc110000-0000-4000-8000-000000000001',true);
set local role authenticated;
select set_config('test.range_equipment',public.create_equipment_with_calibration('DPS','{"name":"[CONTOH] Paired equipment","portfolio_id":"dc220000-0000-4000-8000-000000000001","measurement_ranges":["50 mm Hole","50 mm Wire Diameter"],"measurement_range":"50 mm Hole\n50 mm Wire Diameter"}', '{"calibration_date":"2026-01-01","certificate_number":"[CONTOH] PAIRS","monitoring_measurements":[{"measurement_range":"50 mm Hole","correction_factor":"0,022\n0,023"},{"measurement_range":"50 mm Wire Diameter","correction_factor":"-0,1\n0,2"}]}')::text,true);
select pg_temp.assert_measurement((select jsonb_array_length(measurement_ranges)=2 from public.equipment where id=current_setting('test.range_equipment')::uuid),'two nominal ranges on one asset');
select pg_temp.assert_measurement((select count(*)=1 from public.calibrations where equipment_id=current_setting('test.range_equipment')::uuid),'one certificate, not one record per range');
select pg_temp.assert_measurement((select jsonb_array_length(monitoring_measurements)=2 and monitoring_measurements->1->>'measurement_range'='50 mm Wire Diameter' and monitoring_measurements->1->>'correction_factor'=E'-0,1\n0,2' from public.calibrations where equipment_id=current_setting('test.range_equipment')::uuid),'matching range and correction values persist');
select pg_temp.deny_measurement($q$select public.create_equipment_with_calibration('DPS','{"name":"[CONTOH] Should rollback","measurement_ranges":["Hole","Wire"]}','{"calibration_date":"2026-01-01","monitoring_measurements":[{"measurement_range":"Hole","correction_factor":"1"}]}')$q$);
select pg_temp.assert_measurement(not exists(select 1 from public.equipment where name='[CONTOH] Should rollback'),'invalid factor group count rolls back equipment too');
select pg_temp.deny_measurement($q$update public.equipment set measurement_ranges='[""]' where id=current_setting('test.range_equipment')::uuid$q$);
select set_config('request.jwt.claim.sub','dc110000-0000-4000-8000-000000000002',true);
select pg_temp.deny_measurement($q$select public.create_equipment_with_calibration('DPS','{"name":"[CONTOH] Outside assigned scope","portfolio_id":"dc220000-0000-4000-8000-000000000001","measurement_ranges":["Hole"]}',null)$q$);
reset role;
select pass('Measurement pairs, one asset/certificate, atomic rollback and existing RLS');
select * from finish();
rollback;
